using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using UnityEngine;
using UnityEngine.UI;
namespace Deepsea {
 public sealed partial class SeaLifeRuntime {
  [Serializable] class ReviewReport {public bool passed;public string scope="Standalone game: controller movement, fishing state flow, shore/salvage, physical aquarium placement and collection, isolated save, UI bounds, fixed-view frame sample";public string failure="",resolution,gpu;public List<string> checks=new List<string>(),errors=new List<string>(),warnings=new List<string>();public float boatDisplacement,walkDisplacement;public double fps,p95Ms;public int sampleFrames,fishAtEnd;public bool originalGameplayLoaded;}
  ReviewReport review;bool reviewFailed;
  IEnumerator ReviewDeadline(){yield return new WaitForSecondsRealtime(210);if(review!=null){review.passed=false;review.failure+="review watchdog timeout";Directory.CreateDirectory(Evidence);File.WriteAllText(Evidence+"/result.json",JsonUtility.ToJson(review,true));}Application.Quit(3);}
  void AssertReview(bool condition,string name){review.checks.Add(name+": "+condition);if(!condition){reviewFailed=true;review.failure+=name+"; ";}}
  void ReviewLog(string condition,string stack,LogType type){if(review==null)return;if(type==LogType.Error||type==LogType.Exception||type==LogType.Assert)review.errors.Add(condition);if(type==LogType.Warning)review.warnings.Add(condition);}
  IEnumerator ReviewWalkTo(Vector3 point,string name){float until=Time.time+8;while(Time.time<until){var delta=point-walker.position;delta.y=0;if(delta.magnitude<.55f)break;var local=Quaternion.Euler(0,18,0)*delta.normalized;DriveInput=new Vector2(local.x,local.z);yield return null;}DriveInput=Vector2.zero;var distance=point-walker.position;distance.y=0;AssertReview(distance.magnitude<.65f&&walker.position.y>-.8f,name+" reachable by walking");}
  IEnumerator ReviewShot(string name){for(int i=0;i<4;i++)yield return new WaitForEndOfFrame();var tex=ScreenCapture.CaptureScreenshotAsTexture();int nonblack=0,pink=0;foreach(var p in tex.GetPixels32()){if(p.r+p.g+p.b>40)nonblack++;if(p.r>245&&p.b>245&&p.g<12)pink++;}AssertReview(nonblack>tex.width*tex.height*.12f,name+" visible frame");AssertReview(pink<tex.width*tex.height*.001f,name+" no pink");File.WriteAllBytes(Evidence+"/"+name+".png",tex.EncodeToPNG());Destroy(tex);}
  IEnumerator RunReview(){
   if(review==null)review=new ReviewReport();Directory.CreateDirectory(Evidence);yield return new WaitForSeconds(1);review.resolution=Screen.width+"x"+Screen.height;review.gpu=SystemInfo.graphicsDeviceName;review.originalGameplayLoaded=FindObjectOfType<GameDirector>()!=null;AssertReview(!review.originalGameplayLoaded,"old gameplay entry absent");
   AssertReview(save.fish.Count==0,"review starts with no fixture fish");var start=boat.position;float heading=boat.eulerAngles.y;AutoInput=true;DriveInput=new Vector2(.2f,1);yield return new WaitForSeconds(3);DriveInput=Vector2.zero;review.boatDisplacement=Vector3.Distance(start,boat.position);AssertReview(review.boatDisplacement>2,"actual rigidbody propulsion");AssertReview(Mathf.Abs(Mathf.DeltaAngle(heading,boat.eulerAngles.y))>2,"actual rigidbody steering");yield return ReviewShot("01-sailing");
   PlaceBoat(fishSpots[0]+new Vector3(-1,0,0),90);ApplyCamera(true);AssertReview(BeginFishing(),"prepare rod");AssertReview(Cast(fishSpots[0]),"cast into actual water");yield return new WaitForSeconds(3.2f);AssertReview(fishingStage==3,"float reaches bite state");yield return ReviewShot("02-bite");AssertReview(StartReeling(),"strike starts reeling");float limit=Time.time+25;bool shot=false;while(fishingStage==4&&Time.time<limit){AutoReel=activityTime%2.8f<1.75f;if(!shot&&catchProgress>25){shot=true;yield return ReviewShot("03-reeling");}yield return null;}AutoReel=false;AssertReview(fishingStage==5,"safe hold/release captures fish");yield return ReviewShot("04-catch");var keep=FindObjectsOfType<Button>().FirstOrDefault(b=>b.name=="收进活鱼箱");AssertReview(keep!=null,"capture button exists");if(keep!=null)keep.onClick.Invoke();AssertReview(save.fish.Count==1,"capture commits one unique fish");AssertReview(!KeepCatch()&&save.fish.Count==1,"repeat capture cannot duplicate");
   // Distinct fixture fish are only for the gallery display and transfer checks below.
   save.fish.Add(new SeaLifeFish{id="review-blue",species=1,area="测试样本 · 浅礁"});save.fish.Add(new SeaLifeFish{id="review-gold",species=2,area="测试样本 · 湾口"});
   PlaceBoat(new Vector3(cratePoint.x,Sea,cratePoint.z-2),0);ApplyCamera(true);AssertReview(BeginSalvage(),"lower salvage hook");AutoReel=true;yield return new WaitForSeconds(1.5f);yield return ReviewShot("05-salvage");yield return new WaitForSeconds(2);AutoReel=false;AssertReview(save.salvaged&&!crate.gameObject.activeSelf,"salvage yields one anchor");AssertReview(!BeginSalvage(),"salvage repeat blocked");
   PlaceBoat(dockBerth,90);ToggleBoard();AssertReview(OnFoot&&controller.enabled&&!captain.gameObject.activeSelf,"boarding control and actor visibility");start=walker.position;DriveInput=new Vector2(-1,0);yield return new WaitForSeconds(1);DriveInput=Vector2.zero;review.walkDisplacement=Vector3.Distance(start,walker.position);AssertReview(review.walkDisplacement>1,"actual character-controller walking");AssertReview(walker.position.y>-.8f,"walking remains above sea");
   yield return ReviewWalkTo(new Vector3(-6.4f,0,4.9f),"pier to tide bridge");yield return ReviewWalkTo(tideCenter,"tide ledge");yield return new WaitForSeconds(.5f);AssertReview(walker.position.y<1.2f&&controller.isGrounded,"shore feet on visible shallow ledge");AssertReview(PickupShell(0),"pick physical shore shell");AssertReview(!PickupShell(0),"shore pickup cannot duplicate");yield return ReviewShot("06-shore");
   yield return ReviewWalkTo(new Vector3(-7.8f,0,4.9f),"tide bridge return");yield return ReviewWalkTo(galleryDoor+Vector3.forward*.7f,"gallery front door");Interact();AssertReview(InRoom&&room.gameObject.activeSelf&&!exterior.gameObject.activeSelf,"walk-in gallery entry");SelectedTank=0;OpenPanel(1);yield return ReviewShot("06b-construction");int oldCoins=save.coins;AssertReview(BuildTank(),"place first physical tank");AssertReview(save.coins==oldCoins,"first tank is free");AssertReview(!BuildTank()&&save.coins==oldCoins,"repeat construction no double spending");SelectedTank=1;AssertReview(!BuildTank()&&save.coins==oldCoins,"insufficient coins blocks second tank");SelectedTank=0;foreach(var f in save.fish.ToArray())AssertReview(MoveFish(f.id,0),"move unique fish into tank");AssertReview(CarryCount==0&&TankCount(0)==3,"collection ownership conserved");ChangeTankTheme();ToggleShellDisplay();ToggleAnchorDisplay();Panel=0;ui.RebuildPanel();ApplyCamera(true);yield return new WaitForSeconds(1);yield return ReviewShot("07-aquarium-room");
   CloseView=true;ApplyCamera(true);yield return new WaitForSeconds(1);yield return ReviewShot("08-aquarium-close");CloseView=false;OpenPanel(2);yield return new WaitForSeconds(.3f);yield return ReviewShot("09-fish-management");var id=save.fish[0].id;AssertReview(MoveFish(id,-1),"take fish back from tank");AssertReview(CarryCount==1&&TankCount(0)==2,"transfer back conserves ownership");AssertReview(MoveFish(id,0),"return fish to tank");SaveNow();var loaded=new SeaLifeStore(store.PathName).Load();AssertReview(loaded.fish.Count==save.fish.Count&&loaded.fish.Select(f=>f.id).Distinct().Count()==loaded.fish.Count,"saved unique fish roundtrip");AssertReview(loaded.tanks[0].built&&loaded.salvaged&&loaded.shells[0],"world collection and construction roundtrip");
   var displaySnapshot=JsonUtility.ToJson(save);for(int i=0;i<6;i++)save.fish.Add(new SeaLifeFish{id="capacity-"+i,species=i%3,area="容量测试样本"});AssertReview(!MoveFish(id,-1),"full carry box blocks withdrawal");for(int i=0;i<3;i++)AssertReview(MoveFish("capacity-"+i,0),"tank accepts available slots");AssertReview(!MoveFish("capacity-3",0)&&TankCount(0)==6,"full tank blocks seventh fish");OpenPanel(2);yield return ReviewShot("09b-capacity");save=JsonUtility.FromJson<SeaLifeSave>(displaySnapshot);RefreshCollection();SelectedTank=1;OpenPanel(1);yield return ReviewShot("09c-blocked-construction");SelectedTank=0;OpenPanel(2);
   Screen.SetResolution(1280,720,false);yield return new WaitForSeconds(.7f);Canvas.ForceUpdateCanvases();int outside=0;foreach(var b in FindObjectsOfType<Button>()){if(!b.gameObject.activeInHierarchy)continue;var corners=new Vector3[4];b.GetComponent<RectTransform>().GetWorldCorners(corners);if(corners.Any(p=>p.x< -2||p.y< -2||p.x>Screen.width+2||p.y>Screen.height+2))outside++;}AssertReview(outside==0,"720p visible buttons inside frame");yield return ReviewShot("10-ui-720p");
   Screen.SetResolution(1920,1080,false);Panel=0;ui.RebuildPanel();LeaveRoom();ToggleBoard();PlaceBoat(new Vector3(.8f,Sea,5.2f),100);ApplyCamera(true);yield return new WaitForSeconds(1);var frames=new List<float>();for(int i=0;i<600;i++){yield return null;frames.Add(Time.unscaledDeltaTime);}frames.Sort();review.sampleFrames=frames.Count;review.fps=1/frames.Average();review.p95Ms=frames[Mathf.Clamp(Mathf.FloorToInt(frames.Count*.95f),0,frames.Count-1)]*1000;review.fishAtEnd=save.fish.Count;yield return ReviewShot("11-delivery");review.passed=!reviewFailed&&review.errors.Count==0;File.WriteAllText(Evidence+"/result.json",JsonUtility.ToJson(review,true));Debug.Log("SEA_LIFE_REVIEW_DONE passed="+review.passed+" fps="+review.fps);Application.logMessageReceived-=ReviewLog;Application.Quit(review.passed?0:2);
  }
 }
}
